_root.加载游戏世界人物 = function(id:String, name:String, depth:Number, initObject:Object):MovieClip{
    if(!initObject) {
        initObject = {兵种:id};
    }else{
        initObject.兵种 = id;
    }
    var nest:Object=_root.gameworld.__noahMotherEncounter;
    if(nest!=null && !nest.acceptSpawn(id,initObject))return null;
    org.flashNight.arki.scene.PlayerSceneLifecycle.prepareSpawn(id,name,initObject);
    // Only a newly born, currently controlled historical-CF6 hero gets mask history.
    // Existing actors and other routes are never retroactively declared mask-free.
    var maskRun:Object = _root._saveExt.bookRun;
    if (id === "主角-男" && name === _root.控制目标
        && _root.当前关卡名 === "书中历险-毒刺行动"
        && maskRun.bookId === "cf6-sting" && org.flashNight.arki.scene.BookDefinition.isCf6Route(maskRun.routeId)
        && maskRun.outcome === "active" && maskRun.slot === String(_root.savePath)) {
        var maskInit:Object = org.flashNight.arki.scene.Cf6ActorMaskState.prepare(
            _root.gameworld, _root.gameworld.__stageReturnWorldIdentity, name, initObject);
        var maskActor:MovieClip = _root.gameworld.attachMovie(id, name, depth, maskInit);
        org.flashNight.arki.scene.Cf6ActorMaskState.bind(maskActor, maskInit);
        return maskActor;
    }
    var born:MovieClip=_root.gameworld.attachMovie(id, name, depth, initObject);
    if(nest!=null && born!=undefined)nest.registered(born,initObject);
    return born;
}
_root.根据等级计算值 = function(最小值, 最大值, 目前等级, 允许小数, 禁止超出最大等级, param) {
    if (禁止超出最大等级 === true && 目前等级 > _root.最大等级)
        目前等级 = _root.最大等级;
    var 该等级值 = 最小值 + (最大值 - 最小值) / (_root.最大等级 - 1) * 目前等级;
    if (!允许小数)
        该等级值 = Math.floor(该等级值);
    if (!isNaN(该等级值) && 该等级值 > 0)
        return 该等级值;
    return 1;
}


